# cryo_rocket_builder/build_st_var.py

def get_var_block():
    lines = []
    lines.append("VAR")
    lines.append("    (* ================================================================================================= *)")
    lines.append("    (* 1. DISCRETE STATE-SPACE MODEL MATRICES & VECTORS (6x6 MIMO System at Ts = 1.0 ms)                 *)")
    lines.append("    (* ================================================================================================= *)")
    lines.append("    matA                            : ARRAY[0..5, 0..5] OF REAL; (* Discrete system dynamic state transition matrix A (6x6) *)")
    lines.append("    matB                            : ARRAY[0..5, 0..4] OF REAL; (* Discrete control input transmission matrix B (6x5) *)")
    lines.append("    matC                            : ARRAY[0..5, 0..5] OF REAL; (* Discrete measurement output mapping matrix C (6x6) *)")
    lines.append("    matD                            : ARRAY[0..5, 0..4] OF REAL; (* Discrete direct feedthrough transmission matrix D (6x5) *)")
    lines.append("    matL                            : ARRAY[0..5, 0..5] OF REAL; (* Discrete Luenberger observer / steady Kalman gain matrix L (6x6) *)")
    lines.append("")
    lines.append("    (* State Space Dynamic Vectors *)")
    lines.append("    vecX_est                        : ARRAY[0..5] OF REAL; (* Estimated state vector x[k]: [P_lox, T_lox, P_ch4, T_ch4, P_c, M_he] *)")
    lines.append("    vecX_next                       : ARRAY[0..5] OF REAL; (* Propagated forward state vector x[k+1] *)")
    lines.append("    vecX_ref                        : ARRAY[0..5] OF REAL; (* State reference trajectory tracking setpoint vector *)")
    lines.append("    vecX_corr                       : ARRAY[0..5] OF REAL; (* Corrected state estimation vector after observer innovation *)")
    lines.append("    vecY_meas                       : ARRAY[0..5] OF REAL; (* Measured output telemetry vector y[k] *)")
    lines.append("    vecY_est                        : ARRAY[0..5] OF REAL; (* Estimated output vector y_est[k] = C*x[k] + D*u[k] *)")
    lines.append("    vecInnov                        : ARRAY[0..5] OF REAL; (* Observer measurement residual innovation vector: y_meas - y_est *)")
    lines.append("    vecU_applied                    : ARRAY[0..4] OF REAL; (* Actuator control input vector currently commanded: [u0..u4] *)")
    lines.append("")
    lines.append("    (* ================================================================================================= *)")
    lines.append("    (* 2. RECEDING-HORIZON MPC OPTIMIZER ARRAYS & PARAMETERS (PGD UNROLLED 10 ITERATIONS)                *)")
    lines.append("    (* ================================================================================================= *)")
    lines.append("    vecQ                            : ARRAY[0..5] OF REAL; (* Diagonal state error quadratic penalty weights Q *)")
    lines.append("    vecR                            : ARRAY[0..4] OF REAL; (* Diagonal actuator control effort quadratic penalty weights R *)")
    lines.append("    vecR_rate                       : ARRAY[0..4] OF REAL; (* Diagonal actuator slew rate quadratic penalty weights R_rate *)")
    lines.append("    vecP_terminal                   : ARRAY[0..5] OF REAL; (* Terminal state error quadratic penalty weights P *)")
    lines.append("    vecU_opt                        : ARRAY[0..4] OF REAL; (* Optimal control vector solved by MPC optimizer *)")
    lines.append("    vecU_prev                       : ARRAY[0..4] OF REAL; (* Preceding control command vector for slew rate penalization *)")
    lines.append("    vecU_grad                       : ARRAY[0..4] OF REAL; (* Analytical gradient vector of cost function dJ/du *)")
    lines.append("    vecU_trial                      : ARRAY[0..4] OF REAL; (* Trial step candidate control vector during gradient descent *)")
    lines.append("    vecU_box_min                    : ARRAY[0..4] OF REAL; (* Actuator lower saturation box constraints [%] *)")
    lines.append("    vecU_box_max                    : ARRAY[0..4] OF REAL; (* Actuator upper saturation box constraints [%] *)")
    lines.append("    vecSlewMax_per_scan             : ARRAY[0..4] OF REAL; (* Maximum permissible actuator travel per 1 ms scan [%/scan] *)")
    lines.append("")
    lines.append("    (* MPC Receding Prediction Horizon Storage (Horizon Steps N = 5) *)")
    lines.append("    matX_pred_horiz                 : ARRAY[0..4, 0..5] OF REAL; (* Predicted state trajectory across 5 prediction steps *)")
    lines.append("    matU_pred_horiz                 : ARRAY[0..4, 0..4] OF REAL; (* Predicted actuator control trajectory across horizon *)")
    lines.append("    rCost_State                     : REAL; (* State trajectory tracking quadratic error cost accumulation *)")
    lines.append("    rCost_Input                     : REAL; (* Actuator control effort magnitude quadratic cost accumulation *)")
    lines.append("    rCost_Slew                      : REAL; (* Actuator travel rate-of-change quadratic slew cost accumulation *)")
    lines.append("    rCost_Terminal                  : REAL; (* Terminal prediction horizon state quadratic cost accumulation *)")
    lines.append("    rCost_Total                     : REAL; (* Cumulative composite MPC objective cost function value J *)")
    lines.append("    rAlpha_PGD                      : REAL := 0.0125; (* Projected Gradient Descent (PGD) optimization learning rate / step size *)")
    lines.append("    iPGD_Iter                       : INT;  (* Unrolled PGD loop counter [1..10] *)")
    lines.append("    idx_i                           : INT;  (* General matrix row index loop variable *)")
    lines.append("    idx_j                           : INT;  (* General matrix column index loop variable *)")
    lines.append("    idx_k                           : INT;  (* General state/vector index loop variable *)")
    lines.append("    idx_h                           : INT;  (* MPC prediction horizon step loop variable *)")
    lines.append("")
    lines.append("    (* ================================================================================================= *)")
    lines.append("    (* 3. TRIPLE MODULAR REDUNDANCY (2oo3) VOTING DATA STRUCTURES & TIMERS                               *)")
    lines.append("    (* ================================================================================================= *)")
    lines.append("    (* Bank 1: LOX Feed Manifold Pressure Sensors (PT-101A/B/C) *)")
    lines.append("    rLOX_Diff_12                    : REAL; (* Absolute difference between LOX Ch1 and Ch2 [bar] *)")
    lines.append("    rLOX_Diff_23                    : REAL; (* Absolute difference between LOX Ch2 and Ch3 [bar] *)")
    lines.append("    rLOX_Diff_31                    : REAL; (* Absolute difference between LOX Ch3 and Ch1 [bar] *)")
    lines.append("    rLOX_Timer_12_ms                : REAL; (* Discrepancy accumulation timer between LOX Ch1 and Ch2 [ms] *)")
    lines.append("    rLOX_Timer_23_ms                : REAL; (* Discrepancy accumulation timer between LOX Ch2 and Ch3 [ms] *)")
    lines.append("    rLOX_Timer_31_ms                : REAL; (* Discrepancy accumulation timer between LOX Ch3 and Ch1 [ms] *)")
    lines.append("    bLOX_Ch1_Healthy                : BOOL := TRUE; (* Health status of LOX Feed Pressure Channel A *)")
    lines.append("    bLOX_Ch2_Healthy                : BOOL := TRUE; (* Health status of LOX Feed Pressure Channel B *)")
    lines.append("    bLOX_Ch3_Healthy                : BOOL := TRUE; (* Health status of LOX Feed Pressure Channel C *)")
    lines.append("    bLOX_Discrepancy_Warning        : BOOL; (* Discrepancy threshold exceeded across LOX pressure channels *)")
    lines.append("    rLOX_LastValid                  : REAL := 250.0; (* Bumpless fallback storage for LOX Feed Pressure [bar] *)")
    lines.append("")
    lines.append("    (* Bank 2: LCH4 Feed Manifold Pressure Sensors (PT-102A/B/C) *)")
    lines.append("    rCH4_Diff_12                    : REAL; (* Absolute difference between LCH4 Ch1 and Ch2 [bar] *)")
    lines.append("    rCH4_Diff_23                    : REAL; (* Absolute difference between LCH4 Ch2 and Ch3 [bar] *)")
    lines.append("    rCH4_Diff_31                    : REAL; (* Absolute difference between LCH4 Ch3 and Ch1 [bar] *)")
    lines.append("    rCH4_Timer_12_ms                : REAL; (* Discrepancy accumulation timer between LCH4 Ch1 and Ch2 [ms] *)")
    lines.append("    rCH4_Timer_23_ms                : REAL; (* Discrepancy accumulation timer between LCH4 Ch2 and Ch3 [ms] *)")
    lines.append("    rCH4_Timer_31_ms                : REAL; (* Discrepancy accumulation timer between LCH4 Ch3 and Ch1 [ms] *)")
    lines.append("    bCH4_Ch1_Healthy                : BOOL := TRUE; (* Health status of LCH4 Feed Pressure Channel A *)")
    lines.append("    bCH4_Ch2_Healthy                : BOOL := TRUE; (* Health status of LCH4 Feed Pressure Channel B *)")
    lines.append("    bCH4_Ch3_Healthy                : BOOL := TRUE; (* Health status of LCH4 Feed Pressure Channel C *)")
    lines.append("    bCH4_Discrepancy_Warning        : BOOL; (* Discrepancy threshold exceeded across LCH4 pressure channels *)")
    lines.append("    rCH4_LastValid                  : REAL := 240.0; (* Bumpless fallback storage for LCH4 Feed Pressure [bar] *)")
    lines.append("")
    lines.append("    (* Bank 3: Thrust Chamber Static Pressure Sensors (PT-201A/B/C) *)")
    lines.append("    rPc_Diff_12                     : REAL; (* Absolute difference between Chamber Ch1 and Ch2 [bar] *)")
    lines.append("    rPc_Diff_23                     : REAL; (* Absolute difference between Chamber Ch2 and Ch3 [bar] *)")
    lines.append("    rPc_Diff_31                     : REAL; (* Absolute difference between Chamber Ch3 and Ch1 [bar] *)")
    lines.append("    rPc_Timer_12_ms                 : REAL; (* Discrepancy accumulation timer between Chamber Ch1 and Ch2 [ms] *)")
    lines.append("    rPc_Timer_23_ms                 : REAL; (* Discrepancy accumulation timer between Chamber Ch2 and Ch3 [ms] *)")
    lines.append("    rPc_Timer_31_ms                 : REAL; (* Discrepancy accumulation timer between Chamber Ch3 and Ch1 [ms] *)")
    lines.append("    bPc_Ch1_Healthy                 : BOOL := TRUE; (* Health status of Chamber Pressure Channel A *)")
    lines.append("    bPc_Ch2_Healthy                 : BOOL := TRUE; (* Health status of Chamber Pressure Channel B *)")
    lines.append("    bPc_Ch3_Healthy                 : BOOL := TRUE; (* Health status of Chamber Pressure Channel C *)")
    lines.append("    bPc_Discrepancy_Warning         : BOOL; (* Discrepancy threshold exceeded across Chamber pressure channels *)")
    lines.append("    rPc_LastValid                   : REAL := 1.0; (* Bumpless fallback storage for Chamber Pressure [bar] *)")
    lines.append("")
    lines.append("    (* Bank 4: Hexapod Thrust Load Cell Sensors (LC-301A/B/C) *)")
    lines.append("    rThrust_Diff_12                 : REAL; (* Absolute difference between Thrust Ch1 and Ch2 [kN] *)")
    lines.append("    rThrust_Diff_23                 : REAL; (* Absolute difference between Thrust Ch2 and Ch3 [kN] *)")
    lines.append("    rThrust_Diff_31                 : REAL; (* Absolute difference between Thrust Ch3 and Ch1 [kN] *)")
    lines.append("    rThrust_Timer_12_ms             : REAL; (* Discrepancy accumulation timer between Thrust Ch1 and Ch2 [ms] *)")
    lines.append("    rThrust_Timer_23_ms             : REAL; (* Discrepancy accumulation timer between Thrust Ch2 and Ch3 [ms] *)")
    lines.append("    rThrust_Timer_31_ms             : REAL; (* Discrepancy accumulation timer between Thrust Ch3 and Ch1 [ms] *)")
    lines.append("    bThrust_Ch1_Healthy             : BOOL := TRUE; (* Health status of Thrust Load Cell Channel A *)")
    lines.append("    bThrust_Ch2_Healthy             : BOOL := TRUE; (* Health status of Thrust Load Cell Channel B *)")
    lines.append("    bThrust_Ch3_Healthy             : BOOL := TRUE; (* Health status of Thrust Load Cell Channel C *)")
    lines.append("    bThrust_Discrepancy_Warning     : BOOL; (* Discrepancy threshold exceeded across Thrust load cell channels *)")
    lines.append("    rThrust_LastValid               : REAL := 0.0; (* Bumpless fallback storage for Thrust load [kN] *)")
    lines.append("")
    lines.append("    (* TMR Discrepancy Delta & Persistence Thresholds *)")
    lines.append("    rTMR_PressDiffThresh_bar        : REAL := 6.50; (* Allowable pressure sensor discrepancy delta before timing [bar] *)")
    lines.append("    rTMR_ThrustDiffThresh_kN        : REAL := 35.0; (* Allowable thrust sensor discrepancy delta before timing [kN] *)")
    lines.append("    rTMR_DiscrepancyTripTime_ms     : REAL := 50.0; (* Discrepancy persistence time window before channel invalidation [ms] *)")
    lines.append("")
    lines.append("    (* ================================================================================================= *)")
    lines.append("    (* 4. FIRST-PRINCIPLES CRYOGENIC THERMODYNAMICS & HYDRODYNAMIC PARAMETERS                            *)")
    lines.append("    (* ================================================================================================= *)")
    lines.append("    rRho_LOX                        : REAL := 1141.0; (* Subcooled Liquid Oxygen liquid density [kg/m3] *)")
    lines.append("    rRho_CH4                        : REAL := 424.5;  (* Subcooled Liquid Methane liquid density [kg/m3] *)")
    lines.append("    rR_He                           : REAL := 2077.1; (* Gaseous Helium specific gas constant [J/(kg*K)] *)")
    lines.append("    rGrav_acc                       : REAL := 9.80665; (* Gravitational acceleration constant [m/s2] *)")
    lines.append("    rThroatArea_LOX                 : REAL := 0.001850; (* LOX cavitating venturi throat geometric flow area [m2] *)")
    lines.append("    rThroatArea_CH4                 : REAL := 0.002240; (* LCH4 cavitating venturi throat geometric flow area [m2] *)")
    lines.append("    rCd_LOX                         : REAL := 0.985;  (* LOX cavitating venturi discharge coefficient [-] *)")
    lines.append("    rCd_CH4                         : REAL := 0.980;  (* LCH4 cavitating venturi discharge coefficient [-] *)")
    lines.append("    rUllageTankVolume_m3            : REAL := 12.50;  (* Gaseous helium run tank ullage volume [m3] *)")
    lines.append("    rP_sat_lox                      : REAL; (* Calculated Antoine saturation vapor pressure of LOX [bar] *)")
    lines.append("    rP_sat_ch4                      : REAL; (* Calculated Antoine saturation vapor pressure of LCH4 [bar] *)")
    lines.append("    rLOX_InletVelocity_ms           : REAL; (* LOX turbopump inducer suction flow axial velocity [m/s] *)")
    lines.append("    rCH4_InletVelocity_ms           : REAL; (* LCH4 turbopump inducer suction flow axial velocity [m/s] *)")
    lines.append("    rLOX_DynamicHead_m              : REAL; (* LOX inducer suction dynamic velocity head V^2/(2*g) [m] *)")
    lines.append("    rCH4_DynamicHead_m              : REAL; (* LCH4 inducer suction dynamic velocity head V^2/(2*g) [m] *)")
    lines.append("    rLOX_StaticHeadMargin_m         : REAL; (* LOX inducer suction static pressure head margin (P_s - P_v)/(rho*g) [m] *)")
    lines.append("    rCH4_StaticHeadMargin_m         : REAL; (* LCH4 inducer suction static pressure head margin (P_s - P_v)/(rho*g) [m] *)")
    lines.append("")
    lines.append("    (* ================================================================================================= *)")
    lines.append("    (* 5. 14-STAGE DETERMINISTIC PRODUCTION FSM SEQUENCING TIMERS & PROFILE REGISTERS                   *)")
    lines.append("    (* ================================================================================================= *)")
    lines.append("    rStateTimer_s                   : REAL := 0.0; (* Elapsed runtime spent in current active FSM state [s] *)")
    lines.append("    rProfileTimer_s                 : REAL := 0.0; (* Global hot-fire burn profile elapsed trajectory timer [s] *)")
    lines.append("    iSubPhase                       : INT := 0;    (* Sub-step sequencing phase inside compound states *)")
    lines.append("    bStateEntryExecuted             : BOOL := FALSE; (* One-shot state entry execution latch flag *)")
    lines.append("    rChilldownLockTemp_LOX_K        : REAL := 92.5; (* Maximum allowable LOX feedline temperature for chill lock [K] *)")
    lines.append("    rChilldownLockTemp_CH4_K        : REAL := 115.0; (* Maximum allowable LCH4 feedline temperature for chill lock [K] *)")
    lines.append("    rUllageTargetPress_bar          : REAL := 285.0; (* Nominal run tank target helium ullage blanket pressure [bar] *)")
    lines.append("    rTorchIgniteTimeout_s           : REAL := 2.50;  (* Maximum allowable window for torch lightoff optical confirmation [s] *)")
    lines.append("    rBootstrapTimeout_s             : REAL := 3.20;  (* Chamber bootstrap low-pressure plateau verification duration [s] *)")
    lines.append("    rSteadyHotFireDuration_s        : REAL := 20.00; (* Full rated thrust steady-state hot-fire duration [s] *)")
    lines.append("    rThrottleSweepDuration_s        : REAL := 10.00; (* Deep throttling sweep profile execution duration [s] *)")
    lines.append("    rAcousticEvalDuration_s         : REAL := 6.00;  (* Combustion acoustic resonance evaluation holding duration [s] *)")
    lines.append("    rSteppedShutdownDuration_s      : REAL := 3.50;  (* Controlled stepped derate shutdown sequence duration [s] *)")
    lines.append("    rPostPurgeDuration_s            : REAL := 12.00; (* Post-firing gaseous nitrogen chamber blowdown duration [s] *)")
    lines.append("    rSafeVentDuration_s             : REAL := 25.00; (* Run tank safe depressurization and flare vent duration [s] *)")
    lines.append("")
    lines.append("    (* ================================================================================================= *)")
    lines.append("    (* 6. ISA-18.2 MULTI-TIER PROCESS ALARM SETPOINTS, DEADBANDS, & TELEMETRY REGISTERS                  *)")
    lines.append("    (* ================================================================================================= *)")
    lines.append("    (* Chamber Pressure Redlines & Alarms [bar] *)")
    lines.append("    rAlarm_Pc_LL_Trip               : REAL := 25.0;  (* Combustion blowout low-low redline abort trip [bar] *)")
    lines.append("    rAlarm_Pc_L_Warn                : REAL := 82.0;  (* Chamber pressure low operational warning [bar] *)")
    lines.append("    rAlarm_Pc_H_Warn                : REAL := 112.0; (* Chamber pressure high operational warning [bar] *)")
    lines.append("    rAlarm_Pc_HH_Trip               : REAL := 125.0; (* Chamber overpressure high-high redline abort trip [bar] *)")
    lines.append("    rAlarm_Pc_Deadband              : REAL := 2.0;   (* Chamber pressure alarm clearing hysteresis deadband [bar] *)")
    lines.append("")
    lines.append("    (* Feedline Manifold Pressure Redlines [bar] *)")
    lines.append("    rAlarm_LOX_Press_HH_Trip        : REAL := 325.0; (* LOX feedline overpressure high-high redline trip [bar] *)")
    lines.append("    rAlarm_LOX_Press_LL_Trip        : REAL := 180.0; (* LOX feedline underpressure starvation redline trip [bar] *)")
    lines.append("    rAlarm_CH4_Press_HH_Trip        : REAL := 320.0; (* LCH4 feedline overpressure high-high redline trip [bar] *)")
    lines.append("    rAlarm_CH4_Press_LL_Trip        : REAL := 175.0; (* LCH4 feedline underpressure starvation redline trip [bar] *)")
    lines.append("    rAlarm_FeedPress_Deadband       : REAL := 4.0;   (* Feedline pressure alarm clearing hysteresis deadband [bar] *)")
    lines.append("")
    lines.append("    (* Turbopump Suction NPSM Redlines [m] *)")
    lines.append("    rAlarm_LOX_NPSM_LL_Trip         : REAL := 12.0;  (* LOX pump suction NPSM critical cavitation abort trip [m] *)")
    lines.append("    rAlarm_LOX_NPSM_L_Warn          : REAL := 16.5;  (* LOX pump suction NPSM low operational warning [m] *)")
    lines.append("    rAlarm_CH4_NPSM_LL_Trip         : REAL := 14.5;  (* LCH4 pump suction NPSM critical cavitation abort trip [m] *)")
    lines.append("    rAlarm_CH4_NPSM_L_Warn          : REAL := 18.0;  (* LCH4 pump suction NPSM low operational warning [m] *)")
    lines.append("    rAlarm_NPSM_Deadband            : REAL := 1.0;   (* NPSM alarm clearing hysteresis deadband [m] *)")
    lines.append("")
    lines.append("    (* Acoustic Roughness & Vibration Redlines [bar RMS, g RMS] *)")
    lines.append("    rAlarm_AcousticRough_HH_Trip    : REAL := 15.0;  (* Combustion chamber acoustic roughness high-high redline trip [bar RMS] *)")
    lines.append("    rAlarm_AcousticRough_H_Warn     : REAL := 9.5;   (* Combustion chamber acoustic roughness high warning [bar RMS] *)")
    lines.append("    rAlarm_PumpVib_HH_Trip          : REAL := 45.0;  (* Turbopump high-frequency cavitation vibration trip [g RMS] *)")
    lines.append("    rAlarm_PumpVib_H_Warn           : REAL := 28.0;  (* Turbopump high-frequency cavitation vibration warning [g RMS] *)")
    lines.append("    rAlarm_Vib_Deadband             : REAL := 1.5;   (* Vibration/acoustic clearing hysteresis deadband *)")
    lines.append("")
    lines.append("    (* Mixture Ratio O/F Redlines [-] *)")
    lines.append("    rAlarm_OF_LL_Trip               : REAL := 2.20;  (* Mixture ratio extreme rich low-low redline trip [-] *)")
    lines.append("    rAlarm_OF_L_Warn                : REAL := 2.55;  (* Mixture ratio rich operational warning [-] *)")
    lines.append("    rAlarm_OF_H_Warn                : REAL := 3.05;  (* Mixture ratio lean operational warning [-] *)")
    lines.append("    rAlarm_OF_HH_Trip               : REAL := 3.40;  (* Mixture ratio extreme lean oxidizing high-high trip [-] *)")
    lines.append("    rAlarm_OF_Deadband              : REAL := 0.05;  (* Mixture ratio clearing hysteresis deadband [-] *)")
    lines.append("")
    lines.append("    (* Internal Alarm Active Status Bits *)")
    lines.append("    bTrip_Pc_LL                     : BOOL; (* Chamber pressure blowout low-low trip active *)")
    lines.append("    bTrip_Pc_HH                     : BOOL; (* Chamber overpressure high-high trip active *)")
    lines.append("    bWarn_Pc_L                      : BOOL; (* Chamber pressure low warning active *)")
    lines.append("    bWarn_Pc_H                      : BOOL; (* Chamber pressure high warning active *)")
    lines.append("    bTrip_LOX_Press_HH              : BOOL; (* LOX feedline high-high overpressure trip active *)")
    lines.append("    bTrip_LOX_Press_LL              : BOOL; (* LOX feedline low-low starvation trip active *)")
    lines.append("    bTrip_CH4_Press_HH              : BOOL; (* LCH4 feedline high-high overpressure trip active *)")
    lines.append("    bTrip_CH4_Press_LL              : BOOL; (* LCH4 feedline low-low starvation trip active *)")
    lines.append("    bTrip_LOX_NPSM_LL               : BOOL; (* LOX pump suction NPSM critical cavitation trip active *)")
    lines.append("    bWarn_LOX_NPSM_L                : BOOL; (* LOX pump suction NPSM low warning active *)")
    lines.append("    bTrip_CH4_NPSM_LL               : BOOL; (* LCH4 pump suction NPSM critical cavitation trip active *)")
    lines.append("    bWarn_CH4_NPSM_L                : BOOL; (* LCH4 pump suction NPSM low warning active *)")
    lines.append("    bTrip_Acoustic_HH               : BOOL; (* Combustion dynamic pressure acoustic roughness trip active *)")
    lines.append("    bWarn_Acoustic_H                : BOOL; (* Combustion dynamic pressure acoustic roughness warning active *)")
    lines.append("    bTrip_PumpVib_HH                : BOOL; (* Turbopump bearing cavitation vibration trip active *)")
    lines.append("    bWarn_PumpVib_H                 : BOOL; (* Turbopump bearing cavitation vibration warning active *)")
    lines.append("    bTrip_OF_LL                     : BOOL; (* Mixture ratio rich blowout trip active *)")
    lines.append("    bTrip_OF_HH                     : BOOL; (* Mixture ratio lean thermal burn-through trip active *)")
    lines.append("    bWarn_OF_L                      : BOOL; (* Mixture ratio low warning active *)")
    lines.append("    bWarn_OF_H                      : BOOL; (* Mixture ratio high warning active *)")
    lines.append("    bTrip_LOX_TMR_Fail              : BOOL; (* All 3 LOX pressure channels failed trip active *)")
    lines.append("    bTrip_CH4_TMR_Fail              : BOOL; (* All 3 LCH4 pressure channels failed trip active *)")
    lines.append("    bTrip_Pc_TMR_Fail               : BOOL; (* All 3 Chamber pressure channels failed trip active *)")
    lines.append("    bTrip_Thrust_TMR_Fail           : BOOL; (* All 3 Thrust load cell channels failed trip active *)")
    lines.append("")
    lines.append("    (* Actuator Slew Rate Enforcement & Tracking Variables *)")
    lines.append("    rLOX_Pintle_Actual_Pct          : REAL := 0.0; (* Current filtered position of LOX venturi pintle [%] *)")
    lines.append("    rCH4_Pintle_Actual_Pct          : REAL := 0.0; (* Current filtered position of LCH4 venturi pintle [%] *)")
    lines.append("    rHe_Reg_Actual_Pct              : REAL := 0.0; (* Current filtered position of He ullage regulator [%] *)")
    lines.append("    rLOX_Bleed_Actual_Pct           : REAL := 0.0; (* Current filtered position of LOX bleed valve [%] *)")
    lines.append("    rCH4_Bleed_Actual_Pct           : REAL := 0.0; (* Current filtered position of LCH4 bleed valve [%] *)")
    lines.append("    rPB_Throttle_Actual_Pct         : REAL := 0.0; (* Current filtered position of Preburner throttle [%] *)")
    lines.append("")
    lines.append("    (* System Initialization Latch *)")
    lines.append("    bInitialized                    : BOOL := FALSE; (* Static matrix and system coefficient initialization latch *)")
    lines.append("END_VAR")
    return "\n".join(lines)
